'use client';

import { useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

const BASE = 'https://dylgawidxrgptktapsem.supabase.co/storage/v1/object/public/assets';
const FRAMES = [7, 6, 5, 4, 3, 2].map(n => `${BASE}/${n}.png`);
// how many vh each frame occupies while scrolling
const VH_PER_FRAME = 15;
const TOTAL_SCROLL_VH = VH_PER_FRAME * FRAMES.length;

interface PaperUnravelProps {
  eventName: string;
  date: string;
  type: 'dinner' | 'wine' | 'get-together';
  hostNote: string;
  vibe?: string;
  onRsvp?: (name: string) => void;
}

export default function PaperUnravel({
  eventName,
  date,
  type,
  hostNote,
  vibe,
  onRsvp,
}: PaperUnravelProps) {
  const [frameIdx, setFrameIdx] = useState(0);
  const [showInvite, setShowInvite] = useState(false);
  const [rsvpName, setRsvpName] = useState('');
  const [rsvpNote, setRsvpNote] = useState('');
  const [saved, setSaved] = useState(false);
  const stickyRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    FRAMES.forEach(src => { const img = new Image(); img.src = src; });
  }, []);

  useEffect(() => {
    const onScroll = () => {
      const container = containerRef.current;
      if (!container) return;
      const { top, height } = container.getBoundingClientRect();
      // how far through the scroll container we are (0–1)
      const progress = Math.min(1, Math.max(0, -top / (height - window.innerHeight)));
      const rawIdx = Math.floor(progress * FRAMES.length);
      const idx = Math.min(rawIdx, FRAMES.length - 1);
      setFrameIdx(idx);
      setShowInvite(progress >= 1);
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const handleRsvp = () => {
    if (!rsvpName.trim()) return;
    onRsvp?.(rsvpName.trim());
    setSaved(true);
  };

  const typeLabel = {
    dinner: 'a dinner party',
    wine: 'a wine night',
    'get-together': 'a get-together',
  }[type];

  return (
    // tall scroll container — frames play as you scroll
    <div
      ref={containerRef}
      className="bg-black"
      style={{ height: `${100 + TOTAL_SCROLL_VH}vh` }}
    >
      {/* sticky viewport that holds everything */}
      <div ref={stickyRef} className="sticky top-0 h-screen flex flex-col items-center justify-center overflow-hidden px-4">

        {/* ── FRAME SEQUENCE ── */}
        <div className="relative w-full max-w-[90vw]" style={{ aspectRatio: '4/3' }}>
          {FRAMES.map((src, i) => (
            <motion.img
              key={src}
              src={src}
              alt=""
              className="absolute inset-0 w-full h-full object-contain"
              style={{ opacity: i === frameIdx ? 1 : 0 }}
              animate={i === 0 && frameIdx === 0
                ? { rotate: [0, -4, 4, -2, 2, 0] }
                : { rotate: 0 }
              }
              transition={i === 0 && frameIdx === 0
                ? { duration: 4, repeat: Infinity, ease: 'easeInOut' }
                : { duration: 0.3 }
              }
            />
          ))}
        </div>

        {/* ── SCROLL PROMPT ── */}
        <AnimatePresence>
          {frameIdx === 0 && !showInvite && (
            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: [0.4, 0.9, 0.4] }}
              exit={{ opacity: 0 }}
              transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' }}
              className="text-white/50 text-xs tracking-[0.25em] uppercase mt-4"
            >
              scroll to open
            </motion.p>
          )}
        </AnimatePresence>

        {/* ── INVITATION TEXT ── */}
        <AnimatePresence>
          {showInvite && (
            <motion.div
              key="invite"
              initial={{ opacity: 0, y: 16 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.7, ease: 'easeOut' }}
              className="flex flex-col items-center text-center mt-6 w-full max-w-sm"
            >
              <p
                className="text-xs tracking-[0.25em] uppercase mb-3"
                style={{ color: '#AF4319', fontFamily: 'Georgia, serif' }}
              >
                you're invited to {typeLabel}
              </p>

              <h1
                className="text-4xl font-bold leading-tight mb-2"
                style={{ color: '#6A0136', fontFamily: 'Georgia, serif' }}
              >
                {eventName}
              </h1>

              <p
                className="text-sm mb-4"
                style={{ color: '#c8c8b8', fontFamily: 'Georgia, serif' }}
              >
                {new Date(date).toLocaleDateString('en-US', {
                  weekday: 'long',
                  month: 'long',
                  day: 'numeric',
                })}
              </p>

              <p
                className="text-sm leading-relaxed mb-2"
                style={{ color: '#c8c8b8', fontFamily: 'Georgia, serif' }}
              >
                {hostNote}
              </p>

              {vibe && (
                <p
                  className="text-xs italic mb-6"
                  style={{ color: '#AF4319', fontFamily: 'Georgia, serif' }}
                >
                  {vibe}
                </p>
              )}

              {!saved ? (
                <div className="space-y-3 w-full">
                  <p className="text-xs tracking-[0.15em] uppercase" style={{ color: '#888', fontFamily: 'Georgia, serif' }}>
                    save me a seat
                  </p>
                  <input
                    type="text"
                    placeholder="your name"
                    value={rsvpName}
                    onChange={e => setRsvpName(e.target.value)}
                    className="w-full border-b bg-transparent text-sm py-1.5 outline-none placeholder:text-white/20"
                    style={{ borderColor: '#444', color: '#e8e8d0', fontFamily: 'Georgia, serif' }}
                  />
                  <input
                    type="text"
                    placeholder="a note (optional)"
                    value={rsvpNote}
                    onChange={e => setRsvpNote(e.target.value)}
                    className="w-full border-b bg-transparent text-sm py-1.5 outline-none placeholder:text-white/20"
                    style={{ borderColor: '#444', color: '#e8e8d0', fontFamily: 'Georgia, serif' }}
                  />
                  <button
                    onClick={handleRsvp}
                    className="mt-2 text-sm tracking-widest uppercase py-2 px-6 transition-all hover:opacity-70"
                    style={{ color: 'white', backgroundColor: '#6A0136', fontFamily: 'Georgia, serif', letterSpacing: '0.15em' }}
                  >
                    I'll be there
                  </button>
                </div>
              ) : (
                <p className="text-sm italic" style={{ color: '#c8c8b8', fontFamily: 'Georgia, serif' }}>
                  see you there, {rsvpName}. ✦
                </p>
              )}
            </motion.div>
          )}
        </AnimatePresence>

      </div>

    </div>
  );
}
